import{_ as e,o,c as r,a2 as t}from"./chunks/framework.CqGPl1zp.js";const p="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-%E7%94%B3%E8%AF%B7%E6%B5%8B%E8%AF%95%E5%B8%90%E5%8F%B7.Cy1sVP4e.png",n="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-%E6%B5%8B%E8%AF%95%E8%B4%A6%E5%8F%B7%E4%BF%A1%E6%81%AF.BGD-u5KP.png",l="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-%E6%B7%BB%E5%8A%A0%E5%85%AC%E4%BC%97%E5%8F%B7%E8%B4%A6%E5%8F%B7.DlWneYTP.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%89%E6%AD%A5-%E5%A1%AB%E5%86%99URL%E5%92%8CToken.Cb7QkVRh.png",i="/newx-doc/assets/%E8%A1%A8%E7%BB%93%E6%9E%84.BGPC98Z0.png",d="/newx-doc/assets/%E9%85%8D%E7%BD%AE%E6%8E%A5%E5%85%A5%E5%9B%9E%E8%B0%83.BwD67Zau.png",s="/newx-doc/assets/%E6%B6%88%E6%81%AF%E5%A4%84%E7%90%86.hdGF2pk4.png",u="/newx-doc/assets/%E6%B6%88%E6%81%AF%E5%A4%84%E7%90%86%E5%99%A8.CuyQ56KL.png",B=JSON.parse('{"title":"公众号接入","description":"","frontmatter":{},"headers":[],"relativePath":"mp/account.md","filePath":"mp/account.md","lastUpdated":null}'),m={name:"mp/account.md"};function h(E,a,A,_,b,g){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="公众号接入" tabindex="-1">公众号接入 <a class="header-anchor" href="#公众号接入" aria-label="Permalink to &quot;公众号接入&quot;">​</a></h1><p>本章节，讲解如果将你的公众号，接入到系统中。步骤如下：</p><ul><li>第一步，申请公众号（可选）</li><li>第二步，在系统中，添加公众号账号</li><li>第三步，在公众号中，配置接入信息</li></ul><h2 id="_1-配置步骤" tabindex="-1">1. 配置步骤 <a class="header-anchor" href="#_1-配置步骤" aria-label="Permalink to &quot;1. 配置步骤&quot;">​</a></h2><p>本小节，手把手教你如何将公众号接入到系统中。</p><h3 id="第一步-申请公众号-可选" tabindex="-1">第一步，申请公众号（可选） <a class="header-anchor" href="#第一步-申请公众号-可选" aria-label="Permalink to &quot;第一步，申请公众号（可选）&quot;">​</a></h3><p>友情提示：如果你已经有公众号，可以忽略这一步。</p><p>① 如果你还没有公众号，可以申请一个测试帐号。</p><p><img src="'+p+'" alt="申请测试账号"></p><p>申请地址：<a href="https://mp.weixin.qq.com/debug/cgi-bin/sandbox?t=sandbox/login" target="_blank" rel="noreferrer">微信公众平台接口测试帐号申请</a></p><p>② 申请完成后，获得一个测试号。如下图所示：</p><p><img src="'+n+'" alt="测试账号信息"></p><h3 id="第二步-添加公众号账号" tabindex="-1">第二步，添加公众号账号 <a class="header-anchor" href="#第二步-添加公众号账号" aria-label="Permalink to &quot;第二步，添加公众号账号&quot;">​</a></h3><p>点击 [公众号管理 -&gt; 账号管理] 菜单，添加一个公众号账号。如下图所示：</p><p><img src="'+l+'" alt="添加公众号账号"></p><h3 id="第三步-配置接入信息" tabindex="-1">第三步，配置接入信息 <a class="header-anchor" href="#第三步-配置接入信息" aria-label="Permalink to &quot;第三步，配置接入信息&quot;">​</a></h3><p>① 由于公众号通知需要外网地址，可参考 <a href="./../natapp">《内网穿透》</a> 文档，将本地的 48080 端口，转发到外网中。这里，我的域名是 <code>http://yunai.natapp1.cc</code>。</p><p>② 打开微信公众号界面，填写 URL 和 Token 信息。如下图所示：</p><p><img src="'+c+'" alt="填写 URL 和 Token 信息"></p><p>点击提交后，看到“配置成功”提示，说明配置成功。</p><h2 id="_2-实现代码" tabindex="-1">2. 实现代码 <a class="header-anchor" href="#_2-实现代码" aria-label="Permalink to &quot;2. 实现代码&quot;">​</a></h2><p>本小节，将介绍如何实现公众号接入的代码。</p><h3 id="_2-1-表结构" tabindex="-1">2.1 表结构 <a class="header-anchor" href="#_2-1-表结构" aria-label="Permalink to &quot;2.1 表结构&quot;">​</a></h3><p>公众号账号对应 <code>mp_account</code> 表，结构如下图所示：</p><p><img src="'+i+'" alt="表结构"></p><h3 id="_2-2-账号管理界面" tabindex="-1">2.2 账号管理界面 <a class="header-anchor" href="#_2-2-账号管理界面" aria-label="Permalink to &quot;2.2 账号管理界面&quot;">​</a></h3><ul><li>前端：<a href="https://github.com/yudaocode/yudao-ui-admin-vue2/blob/master/src/views/mp/account/index.vue" target="_blank" rel="noreferrer">/@views/mp/account</a></li><li>后端：<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/account/MpAccountController.java" target="_blank" rel="noreferrer">MpAccountController</a></li></ul><h3 id="_2-3-配置接入回调" tabindex="-1">2.3 配置接入回调 <a class="header-anchor" href="#_2-3-配置接入回调" aria-label="Permalink to &quot;2.3 配置接入回调&quot;">​</a></h3><p>在 <a href="#第三步-配置接入信息">第三步，配置接入信息</a> 时，微信公众号会回调系统的 <code>GET /admin-api/mp/open/{appID}</code> 接口，进行接入配置的验证。对应 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/open/MpOpenController.java#L39-L57" target="_blank" rel="noreferrer">MpOpenController</a> 类的 <code>checkSignature</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+d+'" alt="checkSignature 方法"></p><p>对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/Basic_Information/Access_Overview.html#%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E9%AA%8C%E8%AF%81%E6%B6%88%E6%81%AF%E7%9A%84%E7%A1%AE%E6%9D%A5%E8%87%AA%E5%BE%AE%E4%BF%A1%E6%9C%8D%E5%8A%A1%E5%99%A8" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 接入指南》</a> 文档。</p><p>友情提示：</p><p>项目使用的微信工具开发包是 <a href="https://github.com/Wechat-Group/WxJava/tree/develop/weixin-java-mp" target="_blank" rel="noreferrer"><code>weixin-java-mp</code></a> ，超级好用！</p><h3 id="_2-4-消息处理" tabindex="-1">2.4 消息处理 <a class="header-anchor" href="#_2-4-消息处理" aria-label="Permalink to &quot;2.4 消息处理&quot;">​</a></h3><p>配置接入完成后，用户发给公众号的消息，公众号都会回调到 <code>POST /admin-api/mp/open/{appID}</code> 接口，进行消息的处理。对应 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/open/MpOpenController.java#L59-L114" target="_blank" rel="noreferrer">MpOpenController</a> 类的 <code>handleMessage</code> 方法，如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+s+'" alt="handleMessage 方法"></p><p>核心逻辑是第二步，再解析到消息后，交给 WxMpMessageRouter 进行消息的处理。WxMpMessageRouter 在 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/open/MpOpenController.java#L59-L114" target="_blank" rel="noreferrer">DefaultMpServiceFactory</a> 初始化，设置每种消息对应的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/" target="_blank" rel="noreferrer"><code>handler</code></a> 处理器。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+u+'" alt="消息处理器"></p><p>具体每个处理器的实现，后续每个章节单独详细讲解。</p>',42)])])}const x=e(m,[["render",h]]);export{B as __pageData,x as default};
